function i(e){if(!e)return null;let t=new Date(e);if(Number.isNaN(t.getTime()))return null;let n=new Date,r=n.getFullYear()-t.getFullYear(),o=n.getMonth()-t.getMonth();return (o<0||o===0&&n.getDate()<t.getDate())&&r--,Math.max(r,0)}function s(e){if(!e)return "-";let t=new Date(e);if(Number.isNaN(t.getTime()))return "-";let n=t.getUTCFullYear(),r=String(t.getUTCMonth()+1).padStart(2,"0"),o=String(t.getUTCDate()).padStart(2,"0");return `${n}-${r}-${o}`}function u(e){if(!e)return "";let t=/^(\d{4}-\d{2}-\d{2})/.exec(e);return t?t[1]:""}function l(e){return e.toLowerCase().split(" ").map(t=>t.length>0?t[0].toUpperCase()+t.slice(1):t).join(" ")}function a(e){return [e.primer_nombre,e.segundo_nombre,e.primer_apellido,e.segundo_apellido].filter(t=>!!t&&t.trim().length>0).join(" ")}var g=/^[^\s@]+@[^\s@]+\.[^\s@]+$/,m=/^\d{1,10}$/;function c(){return new Date().toISOString().slice(0,10)}export{a,c,g,i,l,m,s,u};